// ==========================================
// ManuMind AI - Schedule Request Preprocessor
// Purpose:
// Extract scheduling inputs from the webhook
// and prepare them for the AI Scheduler.
// ==========================================

// Get all incoming items
const items = $input.all();

// Process each request
return items.map(item => {

    const request = item.json.body;

    return {
        json: {
            productionTarget: Number(request.production_target),

            productType: request.product_type,

            startTime: request.start_time,

            deliveryDeadline: request.delivery_deadline,

            availableMachines: request.available_machines,

            activeShifts: request.active_shifts
        }
    };

});

// =====================================================
// ManuMind AI - Machine History Aggregator
// Purpose:
// Convert hundreds of historical MongoDB records
// into one compact summary per machine for Gemini.
// =====================================================

const items = $input.all();

// Get MongoDB documents
const documents = items[0]?.json?.documents || [];

// Store aggregated machine information
const machines = {};

// -----------------------------------------------------
// Process historical records
// -----------------------------------------------------

for (const doc of documents) {

    const machineId = doc.machine_id;

    if (!machineId) continue;

    // Create machine entry
    if (!machines[machineId]) {

        machines[machineId] = {
            machine_id: machineId,

            totalRecords: 0,
            runningRecords: 0,
            idleRecords: 0,
            maintenanceRecords: 0,

            totalUnits: 0,
            totalCycleTime: 0,
            cycleTimeRecords: 0,

            totalDowntime: 0,
            totalOEE: 0,

            minMaintenanceDays: Infinity
        };
    }

    const machine = machines[machineId];

    machine.totalRecords++;

    // -------------------------
    // Machine Status
    // -------------------------

    const status = String(doc.status || "").toLowerCase();

    if (status === "running") {
        machine.runningRecords++;
    }

    if (status === "idle") {
        machine.idleRecords++;
    }

    if (status === "maintenance") {
        machine.maintenanceRecords++;
    }

    // -------------------------
    // Production
    // -------------------------

    machine.totalUnits += Number(doc.units_produced || 0);

    // -------------------------
    // Cycle Time
    // Only consider valid running cycle times
    // -------------------------

    const cycleTime = Number(doc.cycle_time_sec || 0);

    if (cycleTime > 0) {
        machine.totalCycleTime += cycleTime;
        machine.cycleTimeRecords++;
    }

    // -------------------------
    // Downtime
    // -------------------------

    machine.totalDowntime += Number(doc.downtime_min || 0);

    // -------------------------
    // OEE
    // -------------------------

    machine.totalOEE += Number(doc.oee_percent || 0);

    // -------------------------
    // Maintenance
    // Keep closest maintenance requirement
    // -------------------------

    const maintenanceDays =
        Number(doc.maintenance_due_days);

    if (
        Number.isFinite(maintenanceDays) &&
        maintenanceDays >= 0
    ) {
        machine.minMaintenanceDays =
            Math.min(
                machine.minMaintenanceDays,
                maintenanceDays
            );
    }
}

// -----------------------------------------------------
// Helper function
// -----------------------------------------------------

const round = (value) =>
    Math.round(value * 10) / 10;

// -----------------------------------------------------
// Generate compact machine summaries
// -----------------------------------------------------

const machineSummary = Object.values(machines).map(machine => {

    const records = machine.totalRecords || 1;

    const averageCycleTime =
        machine.cycleTimeRecords > 0
            ? machine.totalCycleTime / machine.cycleTimeRecords
            : 0;

    const runningPercentage =
        (machine.runningRecords / records) * 100;

    const maintenancePercentage =
        (machine.maintenanceRecords / records) * 100;

    return {

        machine_id: machine.machine_id,

        avg_units_per_record:
            round(machine.totalUnits / records),

        avg_cycle_time_sec:
            round(averageCycleTime),

        avg_downtime_min:
            round(machine.totalDowntime / records),

        avg_oee_percent:
            round(machine.totalOEE / records),

        running_percentage:
            round(runningPercentage),

        maintenance_percentage:
            round(maintenancePercentage),

        maintenance_due_days:
            machine.minMaintenanceDays === Infinity
                ? null
                : machine.minMaintenanceDays
    };
});

// -----------------------------------------------------
// Return ONE item to Gemini
// -----------------------------------------------------

return [
    {
        json: {
            machineSummary: machineSummary
        }
    }
];

// ==========================================
// ManuMind AI - Format Scheduling Response
// Purpose:
// Parse Gemini response and return only the
// data required by the frontend.
// ==========================================

// Get incoming items
const items = $input.all();

// Parse Gemini response
const ai = JSON.parse(items[0].json.response);

// Get schedule start time
const scheduleStartTime =
    ai.schedule.length > 0
        ? ai.schedule[0].startTime
        : null;

// Build frontend response
return [
{
    json: {

        summary: {
            productionTarget: ai.summary.productionTarget,
            maximumPossibleProduction: ai.summary.maximumPossibleProduction,
            remainingUnits: ai.summary.remainingUnits,
            capacityStatus: ai.summary.capacityStatus,

            scheduleStartTime: scheduleStartTime,
            estimatedCompletion: ai.summary.estimatedCompletion,
            deadline: ai.summary.deadline,
            deadlineStatus: ai.summary.deadlineStatus,

            totalMachinesUsed: ai.summary.totalMachinesUsed,
            estimatedDurationHours: ai.summary.estimatedDurationHours
        },

        schedule: ai.schedule.map(task => ({
            machine: task.machine,
            shift: task.shift,
            unitsPerHour: task.unitsPerHour,
            allocatedUnits: task.allocatedUnits,
            startTime: task.startTime,
            endTime: task.endTime,
            estimatedHours: task.estimatedHours
        })),

        insights: ai.insights

    }
}
];
